BEGIN
    RAISE EXCEPTION 'audit_ledger is append-only. UPDATE and DELETE are not allowed.';
END;

BEGIN
  IF NEW.severity IN ('critical', 'high') THEN
    INSERT INTO public.alerts (type, related_entity_id, message, severity)
    VALUES (
      'violation',
      NEW.id,
      'New ' || NEW.severity || ' violation logged. Action required immediately.',
      NEW.severity
    );
  END IF;
  RETURN NEW;
END;
